def same(value):
    return f'{value}'
def nested(value):
    return f'{f"{value}"}'
def convert(value):
    return f'P{value!r}Q{value!a}R'
value=''.join(['é','😀'])
print(same(value) is value, nested(value) is value)
print(convert(value))

def render(record):
    return f"{record['first']:bad}{record['missing']}"
try:
    render({'first':7})
except Exception as error:
    print(type(error).__name__)

events=[]
record={'later':'before'}
class Value:
    def __format__(self,spec):
        events.append('format:'+spec)
        record['later']='after'
        return 'formatted'
record['first']=Value()
def render(value):
    return f"A{value['first']:custom}|{value['later']}Z"
print(render(record),events)

events=[]
class Key:
    def __hash__(self):return hash('missing')
    def __eq__(self,other):
        events.append('equal')
        return False
record={'first':7}
record[Key()]=9
def render(record):
    return f"{record['first']:bad}{record['missing']}"
try:render(record)
except ValueError:print(events)
